import {channelDiscoveryFor} from './channel-discovery';
import {channelAudience} from './eligibility';
import {channelMetricSnapshot} from './channel-authority-snapshots';
import {builtInAccessClass} from './channel-access-class';

const checkedAt = '2026-09-27';
type Entry = Pick<Channel, 'id'|'name'|'domain'|'submitUrl'|'categories'|'kind'|'free'|'freeNote'|'quality'|'qualityReason'|'rulesUrl'|'notes'> &
  Partial<Pick<Channel, 'url'|'contentFormat'|'languages'|'emailRequired'|'accountRequired'|'articleRequired'|'automation'|'allowedHosts'|'enabled'|'checkedAt'|'requirements'|'evidenceSources'|'evidenceStatus'|'linkRel'|'indexable'|'retentionDays'|'audience'|'promotionPolicy'|'promotionPolicySource'|'trial'|'singleSiteOnly'|'irreversible'>>;

function channel(entry: Entry): Channel {
  return {
    url: `https://${entry.domain}/`,
    languages: ['en'],
    emailRequired: true,
    accountRequired: true,
    articleRequired: false,
    automation: 'manual',
    allowedHosts: [entry.domain],
    enabled: true,
    provenance: 'built-in',
    checkedAt,
    metrics:channelMetricSnapshot(entry.domain,entry.id),
    linkRel:'unknown',
    indexable:'unknown',
    audience:channelAudience(entry),
    promotionPolicy:'unknown',
    promotionPolicySource:entry.rulesUrl,
    trial:false,
    singleSiteOnly:false,
    ...entry,
    accessClass:builtInAccessClass({
      id:entry.id,
      automation:entry.automation??'manual',
      accountRequired:entry.accountRequired??true,
      emailRequired:entry.emailRequired??true,
    }),
    evidenceStatus:entry.evidenceSources?.length?entry.evidenceStatus??'rules_checked':'unverified',
  };
}

